package com.fintrack.khmtomnenh.productimage.service; import com.fintrack.khmtomnenh.auth.entity.Auth; import com.fintrack.khmtomnenh.product.entity.Product; import com.fintrack.khmtomnenh.product.repository.ProductRepository; import com.fintrack.khmtomnenh.productimage.dto.ProductImageDto; import com.fintrack.khmtomnenh.productimage.entity.ProductImage; import com.fintrack.khmtomnenh.productimage.repository.ProductImageRepository; import lombok.RequiredArgsConstructor; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class ProductImageService {private final ProductImageRepository repo;private final ProductRepository products;public List<ProductImage> list(Long pid){return repo.findByProductId(pid);} @Transactional public ProductImage create(Long pid,ProductImageDto d,Auth a){Product p=owned(pid,a);return repo.save(ProductImage.builder().product(p).imageUrl(d.imageUrl().trim()).build());}@Transactional public ProductImage update(Long id,ProductImageDto d,Auth a){ProductImage i=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Image not found"));if(!i.getProduct().getCompany().getOwner().getId().equals(a.getId()))throw new AccessDeniedException("Not product owner");i.setImageUrl(d.imageUrl().trim());return i;}@Transactional public void delete(Long id,Auth a){ProductImage i=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Image not found"));if(!i.getProduct().getCompany().getOwner().getId().equals(a.getId()))throw new AccessDeniedException("Not product owner");repo.delete(i);}private Product owned(Long id,Auth a){Product p=products.findById(id).orElseThrow(()->new IllegalArgumentException("Product not found"));if(!p.getCompany().getOwner().getId().equals(a.getId()))throw new AccessDeniedException("Not product owner");return p;}}
